    private function fixFunctions(Tokens $tokens, ConstantCaseFixer $coordinator): void
    {
        for ($index = $tokens->count() - 1; $index >= 0; --$index) {
            if ($tokens[$index]->isGivenKind([T_FUNCTION, T_FN])) {
                foreach ($this->functionsAnalyzer->getFunctionTypeAnalyses($tokens, $index) as $type) {
                    $coordinator->fixNativeTypeHint($tokens, $type, $this->functionTypeHints);
                }
            }
        }
    }

    private function fixClassConstantsAndProperties(Tokens $tokens, ConstantCaseFixer $coordinator): void
    {
        $analyzer = new TokensAnalyzer($tokens);
        $elements = array_reverse($analyzer->getClassyElements(), true);

        foreach ($elements as $index => $element) {
            if ('const' === $element['type']) {
                if (\PHP_VERSION_ID >= 8_03_00 && !$coordinator->isConstWithoutType($tokens, $index)) {
                    $coordinator->fixClassConstantNativeTypes($tokens, $index);
                }

                continue;
            }

            if ('property' === $element['type']) {
                $coordinator->fixPropertyNativeTypes($tokens, $index, $this->beforePropertyTypeTokens);
            }
        }
    }
